#!/usr/bin/env python3
"""Generate all manuscript figures using the supplied boxed-axis publication standard.

This file is genuinely standalone: all curated CSV/GZIP datasets used by the
figures are embedded inside the Python file. It can be copied to any folder and
run without a separate ``data`` directory or the original V4 ZIP archive.

Examples
--------
Run from any folder::

    python generate_all_figures_standardized.py

Choose an output directory::

    python generate_all_figures_standardized.py \
        --output-dir "/absolute/path/to/generated_outputs"

Generate only the six main figures::

    python generate_all_figures_standardized.py --subset main

An external curated data directory may optionally be supplied with
``--data-dir``; otherwise the embedded data are extracted to a temporary
directory for the duration of the run.
"""
from __future__ import annotations

import argparse
import base64
import io
import math
import shutil
import tempfile
import zipfile
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from matplotlib.colors import TwoSlopeNorm
from matplotlib.patches import FancyArrowPatch, Rectangle

