def apply_style() -> None:
    """Apply the publication style supplied by the user.

    The same physical font sizes, black rectangular axes, outward ticks, line
    widths and vector-font settings are used for every main and supplementary
    figure.
    """
    plt.rcParams.update(
        {
            "font.family": "sans-serif",
            "font.sans-serif": ["Arial", "Helvetica", "DejaVu Sans"],
            "font.size": 9,
            "axes.titlesize": 10,
            "axes.labelsize": 12,
            "xtick.labelsize": 10,
            "ytick.labelsize": 10,
            "legend.fontsize": 8,
            "axes.linewidth": 1.2,
            "lines.linewidth": 1.1,
            "lines.markersize": 4.5,
            "xtick.major.width": 0.9,
            "ytick.major.width": 0.9,
            "xtick.major.size": 3.5,
            "ytick.major.size": 3.5,
            "xtick.direction": "out",
            "ytick.direction": "out",
            "pdf.fonttype": 42,
            "ps.fonttype": 42,
            "svg.fonttype": "none",
            "savefig.facecolor": "white",
            "figure.facecolor": "white",
            "axes.facecolor": "white",
            "axes.edgecolor": "black",
            "text.color": "black",
            "axes.labelcolor": "black",
            "xtick.color": "black",
            "ytick.color": "black",
        }
    )


def read_csv(path: Path) -> pd.DataFrame:
    return pd.read_csv(path, keep_default_na=False, low_memory=False)


def numeric(df: pd.DataFrame, columns: list[str]) -> pd.DataFrame:
    out = df.copy()
    for col in columns:
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors="coerce")
    return out


def style_axis(
    ax: plt.Axes,
    grid_axis: str | None = None,
    *,
    tick_length: float = 3.5,
) -> None:
    """Apply a complete black rectangular bounding box to a subplot."""
    for spine in ax.spines.values():
        spine.set_visible(True)
        spine.set_linewidth(1.2)
        spine.set_color("black")

    ax.tick_params(
        axis="both",
        which="both",
        direction="out",
        width=0.9,
        length=tick_length,
        colors="black",
        labelsize=10,
    )

    if grid_axis:
        ax.grid(True, axis=grid_axis, linewidth=0.4, alpha=0.25)
        ax.set_axisbelow(True)
    else:
        ax.grid(False)


def panel_label(ax: plt.Axes, label: str) -> None:
    """Add a bold panel label outside the upper-left corner."""
    ax.text(
        -0.12,
        1.06,
        label,
        transform=ax.transAxes,
        fontsize=12,
        fontweight="bold",
        va="top",
    )


def save_figure(fig: plt.Figure, folder: Path, stem: str) -> None:
    """Save one figure in editable vector and high-resolution raster formats."""
    folder.mkdir(parents=True, exist_ok=True)
    common = {"bbox_inches": "tight", "pad_inches": 0.03, "facecolor": "white"}
    fig.savefig(folder / f"{stem}.pdf", **common)
    fig.savefig(folder / f"{stem}.svg", **common)
    fig.savefig(folder / f"{stem}.png", dpi=OUTPUT_DPI, **common)
    plt.close(fig)


def p_text(value: float) -> str:
    if not np.isfinite(value):
        return "NA"
    if value < 0.001:
        return "<0.001"
    return f"={value:.3f}"


def p_label(prefix: str, value: float) -> str:
    """Format a publication-style P-value label without the awkward 'P=<'."""
    return f"{prefix}{p_text(value)}"


def draw_heatmap(
    ax: plt.Axes,
    matrix: np.ndarray,
    row_labels: list[str],
    col_labels: list[str],
    *,
    cmap: str,
    vmin: float | None = None,
    vmax: float | None = None,
    center: float | None = None,
    annotation: str = ".2f",
    cbar_label: str = "",
    text_scale: float = 1.0,
) -> None:
    if center is None:
        image = ax.imshow(matrix, aspect="auto", cmap=cmap, vmin=vmin, vmax=vmax)
    else:
        max_abs = max(abs(np.nanmin(matrix)), abs(np.nanmax(matrix))) if vmax is None else vmax
        image = ax.imshow(
            matrix,
            aspect="auto",
            cmap=cmap,
            norm=TwoSlopeNorm(vmin=-max_abs, vcenter=center, vmax=max_abs),
        )
    ax.set_xticks(np.arange(len(col_labels)), col_labels, rotation=45, ha="right")
    ax.set_yticks(np.arange(len(row_labels)), row_labels)
    ax.tick_params(length=0)
    for i in range(matrix.shape[0]):
        for j in range(matrix.shape[1]):
            value = matrix[i, j]
            if np.isfinite(value):
                ax.text(
                    j,
                    i,
                    format(value, annotation),
                    ha="center",
                    va="center",
                    fontsize=8.0 * text_scale,
                )
    cbar = plt.colorbar(image, ax=ax, fraction=0.035, pad=0.02)
    cbar.ax.tick_params(labelsize=9, width=0.9, length=3.0, direction="out")
    cbar.outline.set_edgecolor("black")
    cbar.outline.set_linewidth(1.0)
    cbar.set_label(cbar_label, fontsize=10)
    style_axis(ax, tick_length=0.0)


# -----------------------------------------------------------------------------
# Main figures
# -----------------------------------------------------------------------------


def figure_1_design(data_dir: Path, output_dir: Path) -> None:
    inventory = read_csv(data_dir / "main/figure_1_study_inventory.csv")
    quality = numeric(
        read_csv(data_dir / "main/figure_1_quality_retention.csv"),
        ["WindowLength_sec", "RRThreshold", "WindowRetentionPercent", "EligibleBoundaries"],
    )
    values = dict(zip(inventory["Metric"], inventory["Value"]))

    fig = plt.figure(figsize=(12, 6.5))
    grid = fig.add_gridspec(2, 2, hspace=0.50, wspace=0.38)

    # a. Experimental sequence and inventory.
    ax = fig.add_subplot(grid[0, 0])
    ax.set_xlim(0, 8.2)
    ax.set_ylim(-0.8, 1.5)
    for session in range(8):
        condition = "A" if session % 2 == 0 else "NA"
        color = "0.82" if condition == "NA" else "0.55"
        ax.add_patch(Rectangle((session + 0.05, 0.2), 0.9, 0.6, facecolor=color, edgecolor="0.2", linewidth=1.0))
        ax.text(session + 0.5, 0.5, condition, ha="center", va="center", fontsize=10, color="white" if condition == "A" else "black")
        ax.text(session + 0.5, 0.05, f"S{session + 1}", ha="center", va="top", fontsize=10)
        if session < 7:
            ax.axvline(session + 1.0, ymin=0.42, ymax=0.73, color="0.15", linewidth=1.0)
    ax.text(4.0, 1.18, "Alternating affective video sessions", ha="center", fontsize=10, fontweight="bold")
    ax.text(
        4.1,
        -0.38,
        f"{int(values['Participants'])} participants | {int(values['Session boundaries'])} boundaries\n"
        f"{int(values['A-to-NA boundaries'])} A-to-NA | {int(values['NA-to-A boundaries'])} NA-to-A",
        ha="center",
        va="top",
        fontsize=9,
        linespacing=1.25,
    )
    ax.axis("off")
    panel_label(ax, "a")

    # b. Real and pseudo boundary framework.
    ax = fig.add_subplot(grid[0, 1])
    ax.set_xlim(-65, 65)
    ax.set_ylim(-0.1, 3.4)
    ax.axvline(0, color="0.15", linewidth=1.1)
    ax.hlines(2.6, -60, 60, color="0.25", linewidth=1.3)
    ax.scatter([0], [2.6], s=30, color="0.1", zorder=3)
    ax.text(-62, 2.95, "Real session boundary", fontsize=9, fontweight="bold")
    ax.text(-60, 2.35, "preceding session", fontsize=10)
    ax.text(38, 2.35, "subsequent session", fontsize=10)
    for y, label, color in [(1.6, "Stable A pseudo-boundary", COLORS["Stable A pseudo-boundary"]), (0.65, "Stable NA pseudo-boundary", COLORS["Stable NA pseudo-boundary"])]:
        ax.hlines(y, -60, 60, color=color, linewidth=1.3)
        ax.scatter([0], [y], s=30, color=color, zorder=3)
        ax.text(-62, y + 0.28, label, fontsize=9, fontweight="bold")
    ax.set_xlabel("Boundary-relative time (s)")
    ax.set_yticks([])
    ax.set_xticks([-60, -30, 0, 30, 60])
    style_axis(ax)
    panel_label(ax, "b")

    # c. Window retention.
    ax = fig.add_subplot(grid[1, 0])
    for window in [30, 45, 60]:
        sub = quality[quality["WindowLength_sec"] == window].sort_values("RRThreshold")
        ax.plot(
            sub["RRThreshold"],
            sub["WindowRetentionPercent"],
            marker="o",
            color=COLORS[str(window)],
            label=f"{window} s",
        )
    ax.set_xlabel("Maximum corrected RR intervals (%)")
    ax.set_ylabel("Retained windows (%)")
    ax.set_xticks([5, 10, 20])
    ax.set_ylim(80, 101)
    ax.legend(frameon=False, ncol=3, loc="lower right")
    style_axis(ax, "y")
    panel_label(ax, "c")

    # d. Eligible boundaries.
    ax = fig.add_subplot(grid[1, 1])
    for window in [30, 45, 60]:
        sub = quality[quality["WindowLength_sec"] == window].sort_values("RRThreshold")
        ax.plot(
            sub["RRThreshold"],
            sub["EligibleBoundaries"],
            marker="o",
            color=COLORS[str(window)],
            label=f"{window} s",
        )
    ax.axhline(133, color="0.5", linewidth=1.0, linestyle="--")
    ax.set_xlabel("Maximum corrected RR intervals (%)")
    ax.set_ylabel("Eligible real boundaries")
    ax.set_xticks([5, 10, 20])
    ax.set_ylim(95, 136)
    style_axis(ax, "y")
    panel_label(ax, "d")

    fig.suptitle("Study design, matched pseudo-boundary controls, and ECG-quality retention", y=0.995, fontsize=12, fontweight="bold")
    save_figure(fig, output_dir, "Figure_1_study_design_and_quality")


def figure_2_primary_magnitude(data_dir: Path, output_dir: Path) -> None:
    points = numeric(
        read_csv(data_dir / "main/figure_2_participant_magnitude.csv"),
        ["WindowLength_sec", "ParticipantMeanMagnitude", "ParticipantMeanAbsoluteChange"],
    )
    summary = numeric(
        read_csv(data_dir / "main/figure_2_magnitude_summary.csv"),
        [
            "WindowLength_sec", "NA_to_A_Estimate", "A_to_NA_Estimate", "Difference",
            "CI95_Lower", "CI95_Upper", "ParticipantSignFlipPValue", "PValue_Holm3",
        ],
    )
    fig = plt.figure(figsize=(12, 9))
    grid = fig.add_gridspec(2, 3, hspace=0.72, wspace=0.48, height_ratios=[1.15, 1.0])

    for index, window in enumerate([30, 45, 60]):
        ax = fig.add_subplot(grid[0, index])
        sub = points[points["WindowLength_sec"] == window]
        wide = sub.pivot_table(index="Subject", columns="TransitionType", values="ParticipantMeanMagnitude", aggfunc="mean").dropna()
        for _, row in wide.iterrows():
            ax.plot([0, 1], [row["NA_to_A"], row["A_to_NA"]], color="0.75", linewidth=1.1, zorder=1)
        ax.scatter(np.zeros(len(wide)), wide["NA_to_A"], s=24, color=COLORS["NA_to_A"], zorder=2)
        ax.scatter(np.ones(len(wide)), wide["A_to_NA"], s=24, color=COLORS["A_to_NA"], zorder=2)
        ax.set_xticks([0, 1], ["NA-to-A", "A-to-NA"])
        ax.set_title(f"{window}-s windows")
        if index == 0:
            ax.set_ylabel("Participant mean Mahalanobis magnitude")
        style_axis(ax, "y")
        panel_label(ax, chr(ord("a") + index))

    # Forest of primary Mahalanobis differences.
    ax = fig.add_subplot(grid[1, :2])
    forest = summary[summary["Outcome"] == "Mahalanobis effect magnitude"].sort_values("WindowLength_sec")
    y = np.arange(len(forest))[::-1]
    ax.axvline(0, color="0.45", linewidth=1.0)
    ax.errorbar(
        forest["Difference"],
        y,
        xerr=[forest["Difference"] - forest["CI95_Lower"], forest["CI95_Upper"] - forest["Difference"]],
        fmt="o",
        color="0.15",
        ecolor="0.25",
        capsize=2.2,
    )
    ax.set_yticks(y, [f"{int(w)} s" for w in forest["WindowLength_sec"]])
    ax.set_xlabel("A-to-NA minus NA-to-A magnitude")
    ax.set_title("Primary direction contrast")
    ax.set_xlim(-0.05, float(forest["CI95_Upper"].max()) + 0.38)
    for yi, (_, row) in zip(y, forest.iterrows()):
        ax.text(
            row["CI95_Upper"] + 0.035,
            yi,
            p_label("Holm P", float(row["PValue_Holm3"])),
            va="center",
            fontsize=10,
        )
    style_axis(ax, "x")
    panel_label(ax, "d")

    # Secondary absolute standardized change contrast.
    ax = fig.add_subplot(grid[1, 2])
    absolute = summary[summary["Outcome"] == "Mean absolute standardized change"].sort_values("WindowLength_sec")
    x = np.arange(len(absolute))
    bars = ax.bar(x, absolute["Difference"], color=[COLORS[str(int(w))] for w in absolute["WindowLength_sec"]], width=0.62)
    ax.errorbar(
        x,
        absolute["Difference"],
        yerr=[absolute["Difference"] - absolute["CI95_Lower"], absolute["CI95_Upper"] - absolute["Difference"]],
        fmt="none",
        ecolor="0.2",
        capsize=2.0,
        linewidth=1.0,
    )
    ax.set_xticks(x, [f"{int(w)} s" for w in absolute["WindowLength_sec"]])
    ax.set_ylabel("Difference in mean absolute\nstandardized change")
    ax.set_title("Complementary magnitude measure")
    ax.set_ylim(0, float(absolute["CI95_Upper"].max()) * 1.25)
    for bar, (_, row) in zip(bars, absolute.iterrows()):
        ax.text(bar.get_x() + bar.get_width() / 2, bar.get_height() + 0.04, p_label("P", float(row["PValue_Holm3"])), ha="center", fontsize=10)
    style_axis(ax, "y")
    panel_label(ax, "e")

    fig.suptitle("A-to-NA boundaries showed consistently larger cardiovascular change magnitude", y=0.995, fontsize=12, fontweight="bold")
    save_figure(fig, output_dir, "Figure_2_primary_magnitude_asymmetry")


def figure_3_representation_robustness(data_dir: Path, output_dir: Path) -> None:
    data = numeric(
        read_csv(data_dir / "main/figure_3_representation_robustness.csv"),
        [
            "WindowLength_sec", "RepresentationOrder", "Difference", "CI95_Lower", "CI95_Upper",
            "ParticipantSignFlipPValue", "PValue_Holm18",
        ],
    )
    reps = (
        data.sort_values("RepresentationOrder")[["Representation", "RepresentationLabel"]]
        .drop_duplicates()["RepresentationLabel"]
        .tolist()
    )
    columns = [30, 45, 60]
    fig, axes = plt.subplots(1, 2, figsize=(12, 9), gridspec_kw={"wspace": 0.90})
    for ax, outcome, title, cbar in [
        (axes[0], "Mahalanobis magnitude", "Covariance-adjusted magnitude", "A-to-NA minus NA-to-A"),
        (axes[1], "Mean absolute standardized change", "Mean absolute standardized change", "A-to-NA minus NA-to-A"),
    ]:
        subset = data[data["Outcome"] == outcome]
        matrix = np.full((len(reps), len(columns)), np.nan)
        p_matrix = np.full_like(matrix, np.nan)
        for i, label in enumerate(reps):
            for j, window in enumerate(columns):
                row = subset[(subset["RepresentationLabel"] == label) & (subset["WindowLength_sec"] == window)]
                if not row.empty:
                    matrix[i, j] = float(row.iloc[0]["Difference"])
                    p_matrix[i, j] = float(row.iloc[0]["PValue_Holm18"])
        draw_heatmap(
            ax,
            matrix,
            reps,
            [f"{w} s" for w in columns],
            cmap="RdBu_r",
            center=0,
            annotation="+.2f",
            cbar_label=cbar,
            text_scale=0.85,
        )
        for i in range(matrix.shape[0]):
            for j in range(matrix.shape[1]):
                if np.isfinite(p_matrix[i, j]) and p_matrix[i, j] < 0.05:
                    ax.text(j + 0.37, i - 0.34, "*", fontsize=11, fontweight="bold")
        ax.set_title(title)
    panel_label(axes[0], "a")
    panel_label(axes[1], "b")
    fig.suptitle("Magnitude asymmetry across feature representations", y=0.995, fontsize=12, fontweight="bold")
    save_figure(fig, output_dir, "Figure_3_representation_robustness")


def figure_4_real_vs_pseudo(data_dir: Path, output_dir: Path) -> None:
    rates = numeric(
        read_csv(data_dir / "main/figure_4_detection_rates.csv"),
        ["WindowLength_sec", "DetectionRate", "DetectionCI95_Lower", "DetectionCI95_Upper"],
    )
    effects = numeric(
        read_csv(data_dir / "main/figure_4_risk_differences.csv"),
        ["WindowLength_sec", "RiskDifference", "RiskDifferenceCI_Lower", "RiskDifferenceCI_Upper", "PermutationPValue"],
    )
    fig = plt.figure(figsize=(11, 9))
    grid = fig.add_gridspec(2, 2, hspace=0.72, wspace=0.52)
    groups = ["Real boundary", "Stable A pseudo-boundary", "Stable NA pseudo-boundary"]
    for col, direction in enumerate(["NA_to_A", "A_to_NA"]):
        ax = fig.add_subplot(grid[0, col])
        sub = rates[rates["TransitionType"] == direction]
        windows = [30, 45, 60]
        x = np.arange(len(windows))
        width = 0.23
        for gidx, group in enumerate(groups):
            rows = sub[sub["Group"] == group].set_index("WindowLength_sec").reindex(windows)
            values = 100 * rows["DetectionRate"].to_numpy(float)
            lo = 100 * rows["DetectionCI95_Lower"].to_numpy(float)
            hi = 100 * rows["DetectionCI95_Upper"].to_numpy(float)
            xpos = x + (gidx - 1) * width
            ax.bar(xpos, values, width=width, color=COLORS[group], label=group)
            ax.errorbar(xpos, values, yerr=[values - lo, hi - values], fmt="none", ecolor="0.2", linewidth=1.05, capsize=1.8)
        ax.set_xticks(x, [f"{w} s" for w in windows])
        ax.set_xlabel("Window length")
        ax.set_title(DIRECTION_LABELS[direction])
        if col == 0:
            ax.set_ylabel("Detected boundaries (%)")
        ax.set_ylim(0, 17)
        style_axis(ax, "y")
        panel_label(ax, chr(ord("a") + col))
        if col == 1:
            ax.legend(frameon=False, loc="upper right", bbox_to_anchor=(0.99, 0.99))

    for col, direction in enumerate(["NA_to_A", "A_to_NA"]):
        ax = fig.add_subplot(grid[1, col])
        sub = effects[effects["TransitionType"] == direction].copy()
        sub["Label"] = sub.apply(
            lambda row: f"{int(row['WindowLength_sec'])} s vs stable {row['PseudoComparison']}", axis=1
        )
        sub = sub.sort_values(["WindowLength_sec", "PseudoComparison"])
        y = np.arange(len(sub))[::-1]
        ax.axvline(0, color="0.45", linewidth=1.0)
        ax.errorbar(
            100 * sub["RiskDifference"],
            y,
            xerr=[
                100 * (sub["RiskDifference"] - sub["RiskDifferenceCI_Lower"]),
                100 * (sub["RiskDifferenceCI_Upper"] - sub["RiskDifference"]),
            ],
            fmt="o",
            color="0.15",
            capsize=2.0,
        )
        ax.set_yticks(y, sub["Label"])
        ax.set_xlabel("Real minus pseudo detection (percentage points)")
        ax.set_title(f"{DIRECTION_LABELS[direction]} matched contrasts")
        style_axis(ax, "x")
        panel_label(ax, chr(ord("c") + col))
    fig.suptitle("Calibrated individual-boundary detections were uncommon and not consistently greater than pseudo controls", y=0.995, fontsize=12, fontweight="bold")
    save_figure(fig, output_dir, "Figure_4_matched_pseudo_boundary_calibration")


def figure_5_timing(data_dir: Path, output_dir: Path) -> None:
    profiles = numeric(
        read_csv(data_dir / "main/figure_5_timing_profiles.csv"),
        ["WindowLength_sec", "CandidateTime_sec", "Score", "PseudoA_PointwiseQ95", "PseudoNA_PointwiseQ95"],
    )
    summary = numeric(
        read_csv(data_dir / "main/figure_5_timing_summary.csv"),
        [
            "WindowLength_sec", "CandidateTime_sec", "PeakScore", "TimingDualPValue",
            "TimingDualPValue_Holm12", "BootstrapExceedsDualThresholdFraction",
        ],
    )
    nulls = numeric(
        read_csv(data_dir / "main/figure_5_timing_pseudo_null.csv.gz"),
        ["WindowLength_sec", "PeakScore", "CandidateTime_sec"],
    )
    fig = plt.figure(figsize=(11, 9))
    grid = fig.add_gridspec(2, 2, hspace=0.72, wspace=0.48)
    for col, representation in enumerate(["reduced", "independent_pca"]):
        ax = fig.add_subplot(grid[0, col])
        profile = profiles[
            (profiles["WindowLength_sec"] == 45)
            & (profiles["Representation"] == representation)
            & (profiles["TransitionType"] == "A_to_NA")
        ].sort_values("CandidateTime_sec")
        row = summary[
            (summary["WindowLength_sec"] == 45)
            & (summary["Representation"] == representation)
            & (summary["TransitionType"] == "A_to_NA")
        ].iloc[0]
        ax.plot(profile["CandidateTime_sec"], profile["Score"], marker="o", color=COLORS["A_to_NA"], label="Real A-to-NA")
        ax.plot(profile["CandidateTime_sec"], profile["PseudoA_PointwiseQ95"], linestyle="--", color=COLORS["Stable A pseudo-boundary"], label="Stable A, 95th percentile")
        ax.plot(profile["CandidateTime_sec"], profile["PseudoNA_PointwiseQ95"], linestyle=":", color=COLORS["Stable NA pseudo-boundary"], label="Stable NA, 95th percentile")
        ax.axvline(float(row["CandidateTime_sec"]), color="0.25", linewidth=1.0, linestyle="--")
        ax.text(
            0.98,
            0.97,
            p_label("dual P", float(row["TimingDualPValue"])) + "\n" + p_label("Holm P", float(row["TimingDualPValue_Holm12"])),
            transform=ax.transAxes,
            ha="right",
            va="top",
            fontsize=10,
        )
        ax.set_xlabel("Candidate window centre (s)")
        ax.set_ylabel("Participant-normalized timing score")
        ax.set_title(REPRESENTATION_LABELS[representation])
        style_axis(ax, "y")
        panel_label(ax, chr(ord("a") + col))
        if col == 1:
            ax.legend(frameon=False, loc="center right", bbox_to_anchor=(0.98, 0.40))

    # Pseudo-null distributions for reduced and independent PCA.
    ax = fig.add_subplot(grid[1, 0])
    for representation, color, linestyle in [
        ("reduced", COLORS["Reduced"], "-"),
        ("independent_pca", COLORS["Independent PCA"], "--"),
    ]:
        data = nulls[
            (nulls["WindowLength_sec"] == 45)
            & (nulls["Representation"] == representation)
            & (nulls["TransitionType"] == "A_to_NA")
            & (nulls["PseudoCondition"] == "A")
        ]["PeakScore"].to_numpy(float)
        hist, edges = np.histogram(data, bins=35, density=True)
        centres = (edges[:-1] + edges[1:]) / 2
        ax.plot(centres, hist, color=color, linestyle=linestyle, label=f"{REPRESENTATION_LABELS[representation]} stable A")
        real_score = float(
            summary[
                (summary["WindowLength_sec"] == 45)
                & (summary["Representation"] == representation)
                & (summary["TransitionType"] == "A_to_NA")
            ].iloc[0]["PeakScore"]
        )
        ax.axvline(real_score, color=color, linewidth=1.1, linestyle=linestyle)
    ax.set_xlabel("Peak timing score")
    ax.set_ylabel("Density")
    ax.set_title("Stable-session pseudo-null distributions")
    ax.legend(frameon=False)
    style_axis(ax)
    panel_label(ax, "c")

    ax = fig.add_subplot(grid[1, 1])
    rows = summary[
        (summary["WindowLength_sec"] == 45)
        & (summary["TransitionType"] == "A_to_NA")
        & summary["Representation"].isin(["reduced", "independent_pca"])
    ].set_index("Representation")
    reps = ["reduced", "independent_pca"]
    values = [100 * float(rows.loc[rep, "BootstrapExceedsDualThresholdFraction"]) for rep in reps]
    bars = ax.bar(np.arange(2), values, color=[COLORS["Reduced"], COLORS["Independent PCA"]], width=0.62)
    ax.axhline(50, color="0.45", linewidth=1.0, linestyle="--")
    ax.set_xticks(np.arange(2), [REPRESENTATION_LABELS[rep] for rep in reps], rotation=12, ha="right")
    ax.set_ylabel("Bootstrap samples exceeding\ndual pseudo threshold (%)")
    ax.set_ylim(0, 100)
    ax.set_title("Internal bootstrap support")
    for bar, value in zip(bars, values):
        ax.text(bar.get_x() + bar.get_width() / 2, value + 2, f"{value:.1f}", ha="center", fontsize=9)
    style_axis(ax, "y")
    panel_label(ax, "d")
    fig.suptitle("Secondary evidence for an A-to-NA cardiovascular departure within the first 0-45-s interval", y=0.995, fontsize=12, fontweight="bold")
    save_figure(fig, output_dir, "Figure_5_secondary_population_timing")


def figure_6_robustness(data_dir: Path, output_dir: Path) -> None:
    quality = numeric(
        read_csv(data_dir / "main/figure_6_magnitude_quality_sensitivity.csv"),
        ["WindowLength_sec", "RRThreshold", "Difference", "CI95_Lower", "CI95_Upper"],
    )
    lopo = numeric(
        read_csv(data_dir / "main/figure_6_magnitude_lopo.csv"),
        ["WindowLength_sec", "FullSampleDifference", "LeaveOneOutDifference"],
    )
    order = numeric(
        read_csv(data_dir / "main/figure_6_boundary_order_magnitude.csv"),
        ["WindowLength_sec", "BoundaryOrder", "DetectionRate", "MeanMagnitude"],
    )
    fig = plt.figure(figsize=(12, 9))
    grid = fig.add_gridspec(2, 2, hspace=0.72, wspace=0.55)

    ax = fig.add_subplot(grid[0, 0])
    for window in [30, 45, 60]:
        sub = quality[quality["WindowLength_sec"] == window].sort_values("RRThreshold")
        ax.errorbar(
            sub["RRThreshold"],
            sub["Difference"],
            yerr=[sub["Difference"] - sub["CI95_Lower"], sub["CI95_Upper"] - sub["Difference"]],
            marker="o",
            color=COLORS[str(window)],
            capsize=2,
            label=f"{window} s",
        )
    ax.axhline(0, color="0.45", linewidth=1.0)
    ax.set_xticks([5, 10, 20])
    ax.set_xlabel("Maximum corrected RR intervals (%)")
    ax.set_ylabel("A-to-NA minus NA-to-A magnitude")
    ax.set_title("ECG-quality sensitivity")
    ax.legend(frameon=False)
    style_axis(ax, "y")
    panel_label(ax, "a")

    ax = fig.add_subplot(grid[0, 1])
    jitter = {30: -0.14, 45: 0.0, 60: 0.14}
    subjects = sorted(lopo["OmittedSubject"].unique())
    subject_x = {subject: i for i, subject in enumerate(subjects)}
    for window in [30, 45, 60]:
        sub = lopo[lopo["WindowLength_sec"] == window]
        ax.scatter(
            [subject_x[s] + jitter[window] for s in sub["OmittedSubject"]],
            sub["LeaveOneOutDifference"],
            s=30,
            color=COLORS[str(window)],
            label=f"{window} s",
        )
        ax.axhline(float(sub["FullSampleDifference"].iloc[0]), color=COLORS[str(window)], linewidth=1.1, alpha=0.65)
    ax.set_xticks(np.arange(len(subjects)), subjects, rotation=90)
    ax.tick_params(axis="x", labelsize=8)
    ax.set_ylabel("Leave-one-participant-out magnitude difference")
    ax.set_title("Participant influence")
    style_axis(ax, "y")
    panel_label(ax, "b")

    for col, outcome, title, cmap, center, cbar in [
        (0, "MeanMagnitude", "Magnitude by sequence position", "viridis", None, "Mean magnitude"),
        (1, "DetectionRate", "Detection by sequence position", "Blues", None, "Detection rate (%)"),
    ]:
        ax = fig.add_subplot(grid[1, col])
        rows = []
        row_labels = []
        for direction in ["A_to_NA", "NA_to_A"]:
            for window in [30, 45, 60]:
                row_labels.append(f"{DIRECTION_LABELS[direction]}, {window} s")
                vals = []
                for boundary_order in range(1, 8):
                    result = order[
                        (order["TransitionType"] == direction)
                        & (order["WindowLength_sec"] == window)
                        & (order["BoundaryOrder"] == boundary_order)
                    ]
                    value = float(result.iloc[0][outcome]) if not result.empty else np.nan
                    vals.append(100 * value if outcome == "DetectionRate" else value)
                rows.append(vals)
        matrix = np.asarray(rows, dtype=float)
        draw_heatmap(
            ax,
            matrix,
            row_labels,
            [str(i) for i in range(1, 8)],
            cmap=cmap,
            vmin=0 if outcome == "DetectionRate" else None,
            vmax=25 if outcome == "DetectionRate" else None,
            center=center,
            annotation=".1f" if outcome == "DetectionRate" else ".2f",
            cbar_label=cbar,
            text_scale=0.85,
        )
        ax.set_xlabel("Boundary sequence position")
        ax.set_title(title)
        panel_label(ax, chr(ord("c") + col))
    fig.suptitle("Sensitivity to ECG quality, participant omission, and sequence position", y=0.995, fontsize=12, fontweight="bold")
    save_figure(fig, output_dir, "Figure_6_robustness_and_heterogeneity")


