def supplementary_1_method_comparison(data_dir: Path, output_dir: Path) -> None:
    data = numeric(
        read_csv(data_dir / "supplementary/figure_s1_method_comparison.csv"),
        ["MethodOrder", "WindowLength_sec", "RealRate", "SpecificityMargin"],
    )
    methods = data.sort_values("MethodOrder")[["MethodCode", "MethodLabel"]].drop_duplicates()["MethodLabel"].tolist()
    columns = [(window, direction) for window in [30, 45, 60] for direction in ["NA_to_A", "A_to_NA"]]
    labels = [f"{window} s\n{DIRECTION_LABELS[direction]}" for window, direction in columns]
    real_matrix = np.full((len(methods), len(columns)), np.nan)
    margin_matrix = np.full_like(real_matrix, np.nan)
    for i, method in enumerate(methods):
        for j, (window, direction) in enumerate(columns):
            row = data[(data["MethodLabel"] == method) & (data["WindowLength_sec"] == window) & (data["TransitionType"] == direction)]
            if not row.empty:
                real_matrix[i, j] = 100 * float(row.iloc[0]["RealRate"])
                margin_matrix[i, j] = 100 * float(row.iloc[0]["SpecificityMargin"])
    fig, axes = plt.subplots(1, 2, figsize=(12, 8), gridspec_kw={"wspace": 0.90})
    draw_heatmap(axes[0], real_matrix, methods, labels, cmap="Blues", vmin=0, vmax=100, annotation=".0f", cbar_label="Real detection rate (%)")
    draw_heatmap(axes[1], margin_matrix, methods, labels, cmap="RdBu_r", center=0, annotation="+.1f", cbar_label="Real minus maximum pseudo (percentage points)")
    axes[0].set_title("Real-boundary detection")
    axes[1].set_title("Specificity margin")
    panel_label(axes[0], "a")
    panel_label(axes[1], "b")
    fig.suptitle("Change-point method comparison under matched pseudo-boundary calibration", y=0.995, fontsize=12, fontweight="bold")
    save_figure(fig, output_dir, "Figure_S1_method_comparison")


def supplementary_2_simulation(data_dir: Path, output_dir: Path) -> None:
    data = numeric(
        read_csv(data_dir / "supplementary/figure_s2_simulation_power.csv"),
        ["WindowLength_sec", "EffectSizeSD", "DetectionPower", "MedianAbsoluteTimingError_sec", "MethodOrder"],
    )
    keep_labels = ["Covariance-aware IC", "Binary segmentation, L2", "Segmented trend", "CUSUM", "PELT, L2"]
    data = data[data["MethodLabel"].isin(keep_labels)]
    for shape in ["abrupt", "ramp"]:
        fig, axes = plt.subplots(1, 3, figsize=(12, 5.5), sharey=True)
        for index, window in enumerate([30, 45, 60]):
            ax = axes[index]
            sub = data[(data["ChangeShape"] == shape) & (data["WindowLength_sec"] == window) & (data["ChangePosition"] == "middle")]
            for method in keep_labels:
                row = sub[sub["MethodLabel"] == method].sort_values("EffectSizeSD")
                if row.empty:
                    continue
                ax.plot(row["EffectSizeSD"], 100 * row["DetectionPower"], marker="o", label=method)
            ax.set_title(f"{window} s")
            ax.set_xlabel("Injected change (SD)")
            if index == 0:
                ax.set_ylabel("Detection power (%)")
            ax.set_ylim(0, 105)
            style_axis(ax, "y")
            panel_label(ax, chr(ord("a") + index))
        axes[-1].legend(frameon=False, bbox_to_anchor=(1.03, 1), loc="upper left")
        fig.suptitle(f"Simulation power for {shape} multivariate changes", y=0.99, fontsize=12, fontweight="bold")
        save_figure(fig, output_dir, f"Figure_S2_simulation_power_{shape}")


def supplementary_3_fixed_threshold(data_dir: Path, output_dir: Path) -> None:
    data = numeric(
        read_csv(data_dir / "supplementary/figure_s3_fixed_threshold_null_fpr.csv"),
        ["WindowLength_sec", "FalsePositiveRate"],
    ).sort_values("WindowLength_sec")
    fig, ax = plt.subplots(figsize=(8, 6))
    bars = ax.bar(np.arange(len(data)), 100 * data["FalsePositiveRate"], color=[COLORS[str(int(w))] for w in data["WindowLength_sec"]])
    ax.axhline(5, color="0.2", linestyle="--", linewidth=1.1, label="5% target")
    ax.set_xticks(np.arange(len(data)), [f"{int(w)} s" for w in data["WindowLength_sec"]])
    ax.set_ylabel("Null false-positive rate (%)")
    ax.set_ylim(0, 100)
    ax.set_title("Uncalibrated fixed-threshold change-point analysis")
    for bar, value in zip(bars, 100 * data["FalsePositiveRate"]):
        ax.text(bar.get_x() + bar.get_width() / 2, value + 2, f"{value:.1f}", ha="center", fontsize=9)
    ax.legend(frameon=False)
    style_axis(ax, "y")
    save_figure(fig, output_dir, "Figure_S3_fixed_threshold_null_false_positive_rate")


def supplementary_4_feature_direction(data_dir: Path, output_dir: Path) -> None:
    data = numeric(
        read_csv(data_dir / "supplementary/figure_s4_feature_direction.csv"),
        ["WindowLength_sec", "Estimate", "QValue_Global69"],
    )
    features = data["Feature"].drop_duplicates().tolist()
    matrix = np.full((len(features), 3), np.nan)
    qmatrix = np.full_like(matrix, np.nan)
    for i, feature in enumerate(features):
        for j, window in enumerate([30, 45, 60]):
            row = data[(data["Feature"] == feature) & (data["WindowLength_sec"] == window)]
            if not row.empty:
                matrix[i, j] = float(row.iloc[0]["Estimate"])
                qmatrix[i, j] = float(row.iloc[0]["QValue_Global69"])
    fig, ax = plt.subplots(figsize=(8, 10))
    draw_heatmap(ax, matrix, features, ["30 s", "45 s", "60 s"], cmap="RdBu_r", center=0, annotation="+.2f", cbar_label="A-to-NA minus NA-to-A standardized change", text_scale=0.8)
    for i in range(matrix.shape[0]):
        for j in range(matrix.shape[1]):
            if np.isfinite(qmatrix[i, j]) and qmatrix[i, j] < 0.05:
                ax.text(j + 0.37, i - 0.34, "*", fontsize=10, fontweight="bold")
    ax.set_title("Feature-level direction effects after global FDR control")
    save_figure(fig, output_dir, "Figure_S4_feature_direction_heatmap")


def supplementary_5_boundary_order(data_dir: Path, output_dir: Path) -> None:
    data = numeric(
        read_csv(data_dir / "supplementary/figure_s5_boundary_order.csv"),
        ["WindowLength_sec", "BoundaryOrder", "DetectionRate", "MeanMagnitude"],
    )
    fig, axes = plt.subplots(1, 2, figsize=(12, 8), gridspec_kw={"wspace": 0.65})
    for ax, outcome, title, cmap, cbar in [
        (axes[0], "DetectionRate", "Detection rate by sequence position", "Blues", "Detection rate (%)"),
        (axes[1], "MeanMagnitude", "Magnitude by sequence position", "viridis", "Mean magnitude"),
    ]:
        rows = []
        labels = []
        for direction in ["A_to_NA", "NA_to_A"]:
            for window in [30, 45, 60]:
                labels.append(f"{DIRECTION_LABELS[direction]}, {window} s")
                values = []
                for order in range(1, 8):
                    row = data[(data["TransitionType"] == direction) & (data["WindowLength_sec"] == window) & (data["BoundaryOrder"] == order)]
                    value = float(row.iloc[0][outcome]) if not row.empty else np.nan
                    values.append(100 * value if outcome == "DetectionRate" else value)
                rows.append(values)
        matrix = np.asarray(rows)
        draw_heatmap(ax, matrix, labels, [str(i) for i in range(1, 8)], cmap=cmap, vmin=0 if outcome == "DetectionRate" else None, vmax=25 if outcome == "DetectionRate" else None, annotation=".1f" if outcome == "DetectionRate" else ".2f", cbar_label=cbar)
        ax.set_xlabel("Boundary sequence position")
        ax.set_title(title)
    panel_label(axes[0], "a")
    panel_label(axes[1], "b")
    fig.suptitle("Boundary-position heterogeneity", y=0.99, fontsize=12, fontweight="bold")
    save_figure(fig, output_dir, "Figure_S5_boundary_order")


def supplementary_6_timing_lopo(data_dir: Path, output_dir: Path) -> None:
    data = numeric(
        read_csv(data_dir / "supplementary/figure_s6_timing_lopo.csv"),
        ["WindowLength_sec", "CandidateTime_sec", "PeakScore"],
    )
    fig, axes = plt.subplots(2, 2, figsize=(12, 9), sharex=False)
    for row_index, direction in enumerate(["A_to_NA", "NA_to_A"]):
        for col_index, rep in enumerate(["reduced", "independent_pca"]):
            ax = axes[row_index, col_index]
            sub = data[(data["WindowLength_sec"] == 45) & (data["TransitionType"] == direction) & (data["Representation"] == rep)]
            subjects = sorted(sub["OmittedSubject"].unique())
            order_map = {subject: i for i, subject in enumerate(subjects)}
            ax.scatter([order_map[s] for s in sub["OmittedSubject"]], sub["CandidateTime_sec"], s=30, color=COLORS[direction])
            ax.set_xticks(np.arange(len(subjects)), subjects, rotation=90)
            ax.set_ylabel("Candidate centre (s)")
            ax.set_title(f"{DIRECTION_LABELS[direction]}, {REPRESENTATION_LABELS[rep]}")
            style_axis(ax, "y")
            panel_label(ax, chr(ord("a") + row_index * 2 + col_index))
