def write_latex_table(csv_path: Path, tex_path: Path) -> None:
    df = read_csv(csv_path)
    tex_path.write_text(
        df.to_latex(index=False, escape=True, na_rep="", longtable=False),
        encoding="utf-8",
    )


def export_tables(data_dir: Path, output_dir: Path) -> None:
    for source_folder, target_name in [
        (data_dir / "main_tables", "main_tables"),
        (data_dir / "supplementary_tables", "supplementary_tables"),
    ]:
        target = output_dir / target_name
        target.mkdir(parents=True, exist_ok=True)
        for csv_path in sorted(source_folder.glob("*.csv")):
            copied = target / csv_path.name
            shutil.copy2(csv_path, copied)
            write_latex_table(copied, target / f"{csv_path.stem}.tex")


def required_data_files() -> list[Path]:
    """Return the curated files needed to generate every figure."""
    return [
        Path("main/figure_1_study_inventory.csv"),
        Path("main/figure_1_quality_retention.csv"),
        Path("main/figure_2_participant_magnitude.csv"),
        Path("main/figure_2_magnitude_summary.csv"),
        Path("main/figure_3_representation_robustness.csv"),
        Path("main/figure_4_detection_rates.csv"),
        Path("main/figure_4_risk_differences.csv"),
        Path("main/figure_5_timing_summary.csv"),
        Path("main/figure_5_timing_profiles.csv"),
        Path("main/figure_5_timing_pseudo_null.csv.gz"),
        Path("main/figure_5_timing_bootstrap.csv.gz"),
        Path("main/figure_6_magnitude_quality_sensitivity.csv"),
        Path("main/figure_6_magnitude_lopo.csv"),
        Path("main/figure_6_boundary_order_magnitude.csv"),
        Path("supplementary/figure_s1_method_comparison.csv"),
        Path("supplementary/figure_s2_simulation_power.csv"),
        Path("supplementary/figure_s3_fixed_threshold_null_fpr.csv"),
        Path("supplementary/figure_s4_feature_direction.csv"),
        Path("supplementary/figure_s5_boundary_order.csv"),
        Path("supplementary/figure_s6_timing_lopo.csv"),
        Path("supplementary/figure_s7_full_timing_grid.csv"),
        Path("supplementary/figure_s8_timing_power.csv"),
        Path("supplementary/figure_s9_pelt_penalty_grid.csv"),
        Path("supplementary/figure_s10_pseudo_control_availability.csv"),
        Path("supplementary/figure_s11_end_to_end_lopo.csv"),
        Path("supplementary/figure_s12_pca_variance_w30.csv"),
        Path("supplementary/figure_s12_pca_variance_w45.csv"),
        Path("supplementary/figure_s12_pca_variance_w60.csv"),
        Path("supplementary/figure_s12_pca_loadings_w30.csv"),
        Path("supplementary/figure_s12_pca_loadings_w45.csv"),
        Path("supplementary/figure_s12_pca_loadings_w60.csv"),
    ]


def validate_data_dir(data_dir: Path) -> None:
    missing = [str(path) for path in required_data_files() if not (data_dir / path).exists()]
    if missing:
        preview = "\n  - ".join(missing[:12])
        remainder = "" if len(missing) <= 12 else f"\n  ... and {len(missing) - 12} more"
        raise FileNotFoundError(
            "The bundled data directory is incomplete. Missing files:\n  - "
            + preview
            + remainder
            + f"\nResolved data directory: {data_dir}"
        )


def extract_embedded_data() -> tuple[Path, tempfile.TemporaryDirectory[str]]:
    """Extract the embedded curated datasets into a temporary directory."""
    temporary = tempfile.TemporaryDirectory(prefix="ecg_manuscript_data_")
    root = Path(temporary.name)
    payload = base64.b64decode("".join(_EMBEDDED_DATA_ZIP_B64.split()))
    with zipfile.ZipFile(io.BytesIO(payload), mode="r") as archive:
        archive.extractall(root)
    validate_data_dir(root)
    return root, temporary


def copy_table_materials(package_root: Path, data_dir: Path, output_dir: Path) -> None:
    """Write the LaTeX table source and copy machine-readable table CSVs."""
    tables_out = output_dir / "tables"
    tables_out.mkdir(parents=True, exist_ok=True)

    external_tex = package_root / "manuscript_tables.tex"
    if external_tex.exists():
        shutil.copy2(external_tex, tables_out / external_tex.name)
    else:
        tex_bytes = base64.b64decode("".join(_EMBEDDED_TABLES_TEX_B64.split()))
        (tables_out / "manuscript_tables.tex").write_bytes(tex_bytes)

    external_preview = package_root / "manuscript_tables_preview.pdf"
    if external_preview.exists():
        shutil.copy2(external_preview, tables_out / external_preview.name)

    for source_name, target_name in [
        ("main_tables", "main_table_data"),
        ("supplementary_tables", "supplementary_table_data"),
    ]:
        source = data_dir / source_name
        target = tables_out / target_name
        if target.exists():
            shutil.rmtree(target)
        shutil.copytree(source, target)


def main() -> None:
    global OUTPUT_DPI

    parser = argparse.ArgumentParser(
        description=(
            "Generate the six main and twelve supplementary ECG manuscript figures "
            "from data embedded directly in this standalone Python file."
        )
    )
    parser.add_argument(
        "--data-dir",
        type=Path,
        default=None,
        help=(
            "Optional external curated data directory. If omitted, a sibling "
            "data folder is used when present; otherwise the data embedded in "
            "this Python file are extracted automatically."
        ),
    )
    parser.add_argument(
        "--output-dir",
        type=Path,
        default=BASE_DIR / "generated_outputs",
        help="Destination folder (default: generated_outputs next to the script).",
    )
    parser.add_argument(
        "--subset",
        choices=["all", "main", "supplementary"],
        default="all",
        help="Choose whether to generate all, main, or supplementary figures.",
    )
    parser.add_argument(
        "--dpi",
        type=int,
        default=600,
        help="PNG resolution in dots per inch (default: 600).",
    )
    parser.add_argument(
        "--keep-existing",
        action="store_true",
        help="Do not delete the existing output directory before generation.",
    )
    args = parser.parse_args()

    temporary_data: tempfile.TemporaryDirectory[str] | None = None
    if args.data_dir is not None:
        data_dir = args.data_dir.expanduser()
        if not data_dir.is_absolute():
            data_dir = (Path.cwd() / data_dir).resolve()
        else:
            data_dir = data_dir.resolve()
        validate_data_dir(data_dir)
        data_source = "external --data-dir"
    elif (BASE_DIR / "data").is_dir():
        data_dir = (BASE_DIR / "data").resolve()
        validate_data_dir(data_dir)
        data_source = "data folder next to script"
    else:
        data_dir, temporary_data = extract_embedded_data()
        data_source = "embedded datasets"

    output_dir = args.output_dir.expanduser()
    if not output_dir.is_absolute():
        output_dir = (Path.cwd() / output_dir).resolve()
    else:
        output_dir = output_dir.resolve()

    if args.dpi < 150:
        raise ValueError("--dpi must be at least 150; use 600 for submission figures.")
    OUTPUT_DPI = int(args.dpi)

    if output_dir.exists() and not args.keep_existing:
        shutil.rmtree(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    main_figures = output_dir / "main_figures"
    supplementary = output_dir / "supplementary_figures"
    apply_style()

    main_steps = [
        ("Figure 1", figure_1_design, main_figures),
        ("Figure 2", figure_2_primary_magnitude, main_figures),
        ("Figure 3", figure_3_representation_robustness, main_figures),
        ("Figure 4", figure_4_real_vs_pseudo, main_figures),
        ("Figure 5", figure_5_timing, main_figures),
        ("Figure 6", figure_6_robustness, main_figures),
    ]
    supplementary_steps = [
        ("Figure S1", supplementary_1_method_comparison, supplementary),
        ("Figure S2", supplementary_2_simulation, supplementary),
        ("Figure S3", supplementary_3_fixed_threshold, supplementary),
        ("Figure S4", supplementary_4_feature_direction, supplementary),
        ("Figure S5", supplementary_5_boundary_order, supplementary),
        ("Figure S6", supplementary_6_timing_lopo, supplementary),
        ("Figure S7", supplementary_7_timing_grid, supplementary),
        ("Figure S8", supplementary_8_timing_power, supplementary),
        ("Figure S9", supplementary_9_pelt, supplementary),
        ("Figure S10", supplementary_10_pseudo_availability, supplementary),
        ("Figure S11", supplementary_11_end_to_end_lopo, supplementary),
        ("Figure S12", supplementary_12_pca, supplementary),
    ]

    steps: list[tuple[str, object, Path]] = []
    if args.subset in {"all", "main"}:
        steps.extend(main_steps)
    if args.subset in {"all", "supplementary"}:
        steps.extend(supplementary_steps)

    print(f"Script directory : {BASE_DIR}", flush=True)
    print(f"Data source      : {data_source}", flush=True)
    print(f"Data directory   : {data_dir}", flush=True)
    print(f"Output directory : {output_dir}", flush=True)
    print(f"PNG resolution   : {OUTPUT_DPI} dpi", flush=True)

    for label, function, folder in steps:
        print(f"Generating {label}...", flush=True)
        function(data_dir, folder)

    copy_table_materials(BASE_DIR, data_dir, output_dir)
    print("Completed successfully.", flush=True)
    print(f"Main figures          : {main_figures}", flush=True)
    print(f"Supplementary figures : {supplementary}", flush=True)
    print(f"Tables and captions   : {output_dir / 'tables'}", flush=True)

    if temporary_data is not None:
        temporary_data.cleanup()


if __name__ == "__main__":
    main()
